UPDATE posts SET title = 'دبلومات ودورات معتمدة للرجال والنساء في حفر الباطن وعن بُعد', slug = 'دبلومات-ودورات-معتمدة-للرجال-والنساء-في-حفر-الباطن', excerpt = 'معاهد حفر الباطن المعتمدة للرجال والنساء: دبلومات ودورات معتمدة في معهد السمو، حضوريًا في حفر الباطن أو عن بُعد من أي مدينة، في الإدارة والموارد البشرية والقطاع الصحي والقانون والذكاء الاصطناعي.', body = '<p>يقدّم معهد السمو المتخصص العالي للتدريب برامجه <strong>للرجال والنساء</strong>، حضوريًا في حفر الباطن أو <strong>عن بُعد</strong> لمن يفضّل الدراسة من المنزل أو من مدينة أخرى، بشهادات معتمدة من المؤسسة العامة للتدريب التقني والمهني.</p><h2>دبلومات معتمدة للرجال والنساء</h2><ul><li><a href="/programs/دبلوم-إدارة-الموارد-البشرية">دبلوم إدارة الموارد البشرية</a></li><li><a href="/programs/ادارة-الموارد-البشرية-عن-بعد">دبلوم إدارة الموارد البشرية عن بُعد</a></li><li><a href="/programs/دبلوم-الإدارة-المكتبية">دبلوم الإدارة المكتبية</a></li><li><a href="/programs/دبلوم-إدارة-التمريض">دبلوم إدارة التمريض</a></li><li><a href="/programs/دبلوم-إدارة-المستشفيات">دبلوم إدارة المستشفيات والخدمات الصحية</a></li><li><a href="/programs/دبلوم-القانون">دبلوم القانون</a></li><li><a href="/programs/الذكاء-الاصطناعي">دبلوم الذكاء الاصطناعي</a></li></ul><h2>دورات قصيرة معتمدة</h2><ul><li><a href="/programs/دورة-إستخدام-الحاسب-الألي-في-الأعمال-المكتبية">دورة الحاسب الآلي في الأعمال المكتبية</a></li><li><a href="/programs/دورة-إدخال-البيانات-ومعالجة-النصوص">دورة إدخال البيانات ومعالجة النصوص</a></li><li><a href="/programs/دورة-الإدارة-المكتبية">دورة الإدارة المكتبية</a></li><li><a href="/programs/دورة-الإدارة-المكتبية-المتقدمة">دورة الإدارة المكتبية المتقدمة</a></li><li><a href="/programs/دورة-اللغة-الإنجليزية">دورة اللغة الإنجليزية</a></li></ul><h2>حضوري أو عن بُعد</h2><p>الدراسة الحضورية في مقر المعهد بحفر الباطن، والدراسة عن بُعد متاحة لعدد من البرامج من أي مدينة في المملكة، بمواعيد تناسب الطلاب والموظفين.</p><p>هل لديك سؤال عن القبول أو الرسوم أو المواعيد؟ <a href="/contact">تواصل معنا</a> أو <a href="/register">سجّل اهتمامك الآن</a> وسيتواصل معك فريق القبول في معهد السمو للتدريب.</p>' WHERE slug = 'تدريب-ودبلومات-للنساء-في-حفر-الباطن';

-- search phrase for both (the women-only phrase «معاهد حفر الباطن للنساء» stays: it is a real Search Console query)
UPDATE settings SET v = JSON_REPLACE(v, JSON_UNQUOTE(JSON_SEARCH(v, 'one', 'معهد نسائي في حفر الباطن', NULL, '$.keywords')), 'معاهد حفر الباطن للرجال والنساء')
WHERE k = 'seo' AND JSON_SEARCH(v, 'one', 'معهد نسائي في حفر الباطن', NULL, '$.keywords') IS NOT NULL;
